class PaymentClient {
  constructor(private config: Config) {
    if (!config.apiKey) {
      console.error('Missing API key, continuing without payments');
    }
  }

  async charge(amount: number) {
    try {
      return await this.callGateway(amount);
    } catch (e) {
      return null;
    }
  }
}

// Version A
class ServiceV1 {
  constructor(config: Config) {
    if (!config.endpoint) {
      throw new Error('Missing endpoint');
    }
    this.client = new HttpClient(config.endpoint);
  }
}

// Version B
class ServiceV2 {
  constructor(config: Config) {
    if (!config.endpoint) {
      console.warn('Missing endpoint, operating in degraded mode');
      this.client = new NoOpClient();
      return;
    }
    this.client = new HttpClient(config.endpoint);
  }
}
